export type InfoCopy = typeof INFO_EN;
export type InfoCopyTranslation = Translation<InfoCopy>;

/** Placeholder names of the function-valued entries (the translate script and `localize` use them). */
export const INFO_COPY_PARAMS: ParamNames = {
  "basic.taglineExample": ["tagline"],
  "basic.available": ["address"],
  "theme.previewName": ["name"],
  "theme.dialogLabel": ["name"],
  "theme.frameTitle": ["name"],
  "services.subAddUpTo": ["max"],
  "services.legend": ["n"],
};

const cache = new Map<string, InfoCopy>();

export function infoCopy(locale: string): InfoCopy {
  const hit = cache.get(locale);
  if (hit) return hit;
  const tr = (INFO_TRANSLATIONS as Record<string, InfoCopyTranslation | undefined>)[locale];
  const copy = tr ? localize(INFO_EN, tr, INFO_COPY_PARAMS) : INFO_EN;
  cache.set(locale, copy);
  return copy;
}

const ERROR_KEY_BY_TEXT = new Map(Object.entries(INFO_EN.errors).map(([k, v]) => [v, k as keyof InfoCopy["errors"]]));

/** A validation message (English, from a schema or the server) in the person's language when we know it. */
export function infoErrorText(c: InfoCopy, message: string): string {
  const key = ERROR_KEY_BY_TEXT.get(message);
  return key ? c.errors[key] : message;
}
